import vuedraggable from 'vuedraggable';
import goodsList from '@/components/goodsList';
import sortList from '@/components/sortList';
export default {
  name: 'c_goods',
  props: {
    name: {
      type: String
    },
    configData: {
      type: null
    }
  },
  components: {
    goodsList: goodsList,
    sortList: sortList,
    draggable: vuedraggable
  },
  watch: {
    configData: {
      handler: function handler(nVal, oVal) {
        this.defaults = nVal;
        this.type = nVal.selectConfig ? nVal.selectConfig.type ? nVal.selectConfig.type : '' : '';
        // this.type = nVal.selectConfig.type?nVal.selectConfig.type:''
      },
      immediate: true,
      deep: true
    }
  },
  data: function data() {
    return {
      modals: false,
      goodsList: [],
      tempGoods: [],
      defaults: {},
      type: '',
      is_new: '',
      loading: true
    };
  },
  created: function created() {
    this.defaults = this.configData;
    this.is_new = this.configData.is_new;
  },
  methods: {
    getProductDiy: function getProductDiy(data) {
      this.tempGoods = data;
      this.loading = false;
    },
    cancel: function cancel() {
      this.tempGoods = [];
    },
    //对象数组去重；
    unique: function unique(arr) {
      var res = new Map();
      return arr.filter(function (arr) {
        return !res.has(arr.id) && res.set(arr.id, 1);
      });
    },
    ok: function ok() {
      if (!this.tempGoods.length) {
        return this.$Message.warning('请先选择商品');
      }
      var list = this.defaults.goodsList.list;
      list.push.apply(list, this.tempGoods);
      // list.push(this.tempGoods);
      var picList = this.unique(list);
      this.defaults.goodsList.list = picList;
      // this.defaults.goodsList.list.push(this.tempGoods);
    },
    bindDelete: function bindDelete(index) {
      this.defaults.goodsList.list.splice(index, 1);
    }
  }
};
